        ll length = 0;
        while(n > 0){
            int digit = n % 10;
            length = (length + powmod(10, m) * (digit + 1)) % MOD;
            n /= 10;
        }
        ll result = 0;
        ll current = 1;
        while(length > 0){
            result = (result + current * (length % 10)) % MOD;
            current = current * 10 % MOD;
            length /= 10;
        }
        cout << result << "\n";
    }
}

