double dfs(int u, int p) {
    visited[u] = true;
    int size = 1;
    vector<int> component_sizes;
    for (int v : adj[u]) {
        if (v != p && !visited[v]) {
            component_sizes.push_back(dfs(v, u));
            size += component_sizes.back();
        }
    }
    double res = size;
    for (int s : component_sizes) {
        res += (double)s / (size - 1) * dfs(v, u);
    }
    return res;
}

