    int n, m;
    cin >> n >> m;
    for(int i=0; i<m; i++){
        int x, y, k;
        cin >> x >> y >> k;
        vector<int> vis(k);
        for(int j=0; j<k; j++){
            cin >> vis[j];
        }
        adj[x].push_back({y, vis});
    }
    //find_path(n);
    count_paths(n);
}

