    for(int i = 0; i < q; ++i){
        cin >> l[i] >> r[i];
        --l[i], --r[i];
    }
    vector<vector<int>> queries(n, vector<int>(n, -1));
    for(int i = 0; i < q; ++i){
        queries[l[i]][r[i]] = i;
    }
    UF uf(n);
    vector<int> ans(q);
    for(int s = m-1; s >= 0; --s){
        for(int i = 0; i < n; ++i){
            for(int j = i+1; j < n; ++j){
                if(queries[i][j] != -1 && uf.find(i) == uf.find(j)){
                    ans[queries[i][j]] = get<2>(roads[s]);
