    vector<int> degree(n + 1, 0);
    for (int i = 1; i <= n; ++i) {
        int p;
        cin >> p;
        if (p != 0) {
            adj[p].push_back(i);
            adj[i].push_back(p);
            degree[p]++;
            degree[i]++;
        }
    }

    queue<int> q;
    for (int i = 1; i <= n; ++i) {
        if (degree[i] % 2 == 0 && degree[i] > 0) {
