            if (degree[v] > 0) {
                degree[v]--;
                if (degree[v] % 2 == 0 && degree[v] > 0) {
                    q.push(v);
                }
            }
        }
        degree[u] = 0;
    }

    if (order.size() < n) {
        cout << "NO";
    } else {
        cout << "YES\n";
        for (int u : order) {
            cout << u << "\n";
        }
