bool isZigzag(const std::string& num) {
    if (num.size() == 1) return true;
    for (size_t i = 1; i < num.size(); ++i) {
        if ((i % 2 == 1 && num[i] <= num[i - 1]) || (i % 2 == 0 && num[i] >= num[i - 1])) {
            return false;
        }
    }
    return true;
}

int main() {
    std::string A, B;
    int M;
    std::cin >> A >> B >> M;

    std::string current = A;
    while (true) {
        bool carry = false;
        for (int i = current.size() - 1; i >= 0; --i) {
            int digit = current[i] - '0' + (carry ? 1 : 0);
            digit %= 10;
            current[i] = digit + '0';
            carry = (digit == 0);
            if (!carry) break;
        }
        if (carry) current = "1" + current;

        if (current > B) break;

        std::string modStr;
        long long modValue = 0;
        for (char c : current) {
            modValue = (modValue * 10 + (c - '0')) % M;
        }
        if (modValue == 0 && isZigzag(current)) {
            std::cout << current << std::endl;
        }
    }

    long long count = 0;
    for (long long i = std::stoll(A); i <= std::stoll(B); i += M) {
        if (isZigzag(std::to_string(i))) {
            count++;
        }
    }

    std::cout << count % 10000 << std::endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long double ld;

struct Edge {
    int to;
    ld cap;
    int rev;
};

vector<vector<Edge>> G;
vector<ld> cost;
vector<int> prevv, preve;

bool min_cost_flow_bfs(int s, int t, vector<ld>& dist) {
    int n = G.size();
    dist.assign(n, numeric_limits<ld>::max());
    dist[s] = 0;
    queue<int> que;
    que.push(s);
    while (!que.empty()) {
        int v = que.front(); que.pop();
        for (int i = 0; i < G[v].size(); i++) {
            Edge &e = G[v][i];
            if (e.cap > 0 && dist[e.to] > dist[v] + cost[i]) {
                dist[e.to] = dist[v] + cost[i];
                prevv[e.to] = v;
                preve[e.to] = i;
                que.push(e.to);
            }
        }
    }
    return dist[t] < numeric_limits<ld>::max();
}

ld min_cost_flow(int s, int t, ld f) {
    int n = G.size();
    vector<ld> dist;
    ld res = 0;
    while (f > 0) {
        if (!min_cost_flow_bfs(s, t, dist)) return -1;
        ld d = f;
        for (int v = t; v != s; v = prevv[v]) {
            d = min(d, G[prevv[v]][preve[v]].cap);
        }
        f -= d;
        res += d * dist[t];
        for (int v = t; v != s; v = prevv[v]) {
            Edge &e = G[prevv[v]][preve[v]];
            e.cap -= d;
            G[v][e.rev].cap += d;
        }
    }
    return res;
}

ld calcDamage(const vector<ld>& temperatures, vector<vector<int>>& pipeline) {
    ld sum = 0;
    for (int i = 0; i < pipeline.size(); i++) {
        for (int j = 0; j < pipeline[i].size(); j++) {
            int to = pipeline[i][j];
            sum += abs(temperatures[i] - temperatures[to]);
        }
    }
    return sum;
}

