                }
                for (int j = 0; j < N + 1; j++) {
                    if (i != j) {
                        for (int k = i + 1; k <= N; k++) {
                            tempCoefficientsLD[j][k] -= tempCoefficientsLD[j][i] * tempCoefficientsLD[i][k];
                        }
                    }
                }
            }
