            }
            sort(new_cp.begin(), new_cp.end(), [](PDD a, PDD b){
                return a.first < b.first || (fabs(a.first - b.first) < EPS && a.second < b.second);
            });
            new_cp.erase(unique(new_cp.begin(), new_cp.end(), [](PDD a, PDD b){
