}

vector<pair<ll, ll>> addVector(vector<pair<ll, ll>> vec, pair<ll, ll> c) {
    vector<pair<ll, ll>> res;
    for (auto p : vec) {
        res.emplace_back(p.first + c.first, p.second + c.second);
    }
    return res;
}

