#include <bits/stdc++.h>
using namespace std;

const int MAXN = 100005;
const int MAXK = 100005;
const long long INF = 1e18;

vector<pair<int, long long>> adj[MAXN];

struct Edge {
    int from, to;
    long long weight;
};

int k, q;
vector<Edge> edges;
int central_id[MAXN];

struct Query {
    int from, to, index;
};

vector<Query> queries;

long long dist[MAXK][MAXK];

void dijkstra(int start, int k, long long dist[MAXK][MAXK]) {
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;
    pq.push({0, start});
    dist[start][start] = 0;
    while (!pq.empty()) {
        long long d = pq.top().first;
        int u = pq.top().second;
        pq.pop();
        if (central_id[u] != -1) {
            if (dist[start][central_id[u]] > d) {
                dist[start][central_id[u]] = d;
            }
        }
        for (auto &edge : adj[u]) {
            int v = edge.first;
            long long w = edge.second;
            if (central_id[v] != -1) {
                if (dist[start][central_id[v]] > d + w) {
                    dist[start][central_id[v]] = d + w;
                    pq.push({d + w, v});
                }
            } else {
                if (dist[start][central_id[u]] > d + w) {
                    dist[start][central_id[u]] = d + w;
                    pq.push({d + w, v});
                }
            }
        }
    }
}

