#include <bits/stdc++.h>
using namespace std;

const int MAXN = 1e5 + 5;

int n, m;
vector<int> adj[MAXN];
int in_degree[MAXN];
int out_degree[MAXN];
bool visited[MAXN];

void dfs(int node, vector<int> &path) {
    visited[node] = true;
    path.push_back(node);
    for (int next : adj[node]) {
        if (!visited[next]) {
            dfs(next, path);
        }
    }
}

pair<int, vector<int>> findSCC(int node) {
    memset(visited, false, sizeof(visited));
    vector<int> path;
    dfs(node, path);
    memset(visited, false, sizeof(visited));
    int scc_size = 0;
    vector<int> scc;
    for (int x : path) {
        for (int next : adj[x]) {
            if (find(path.begin(), path.end(), next) != path.end()) {
                if (!visited[next]) {
                    visited[next] = true;
                    scc_size++;
                    scc.push_back(next);
                }
            }
        }
    }
    return {scc_size, scc};
}

