        vector<int> tags(n);
        vector<long long> scores(n);
        for(int i=0;i<n;i++) cin >> tags[i];
        for(int i=0;i<n;i++) cin >> scores[i];
        vector<vector<long long>> dp(n, vector<long long>(1<<16, LLONG_MIN));
        for(int i=0;i<n;i++){
            dp[i][1<<tags[i]] = scores[i];
        }
