    ll n, k, s, t;
    cin >> n >> k >> s >> t;
    vector<pair<ll, ll>> cars;
    for(int i=0;i<n;i++){
        ll c, v;
        cin >> c >> v;
        cars.push_back({c, v});
    }
    set<int> gas_stations;
    for(int i=0;i<k;i++){
        int g;
        cin >> g;
        gas_stations.insert(g);
    }

    sort(cars.begin(), cars.end());

    ll ans = -1;
    for(auto &[c, v] : cars){
        if(can_reach(v, s, t, k, gas_stations)){
            ans = c;
            break;
        }
    }

    cout << ans;
}

