        }
    }
    for(int i=0;i<n;i++){
        for(int j=0;j<m;j++){
            if(grid[i][j] != '.'){
                if(scores[i][j] == 0){
                    int score = bfs(i, j);
                    if(score > maxScore){
                        maxScore = score;
                        countMaxScore = 1;
                    }
                    else if(score == maxScore){
                        countMaxScore++;
                    }
                }
            }
        }
    }
    cout << maxScore << " " << countMaxScore;
}

