long long dp[1<<18];

double evaluate(int n, long long dp[]) {
    double res = 0;
    for (int i = 0; i < (1 << n); ++i) {
        res += dp[i];
    }
    return res / (1 << n);
}

void update_dp(int n, int pos, long long val, long long dp[]) {
    for (int mask = 0; mask < (1 << n); ++mask) {
        if ((mask & (1 << pos)) == 0) {
            dp[mask] -= val;
            dp[mask | (1 << pos)] += val;
        }
    }
}

int main(){
    ios::sync_with_stdio(false);
