    for(auto &i: f) cin >> i;
    copy(f.begin(), f.end(), dp);
    for(int i=0;i<n;++i){
        for(int mask = (1<<n)-1;mask>=0;--mask){
            if(mask & (1<<i)){
                dp[mask] -= f[mask];
                dp[mask^(1<<i)] += f[mask];
            }
        }
    }
    cout << fixed << setprecision(6);
    cout << evaluate(n, dp) << "\n";
    for(int i=0;i<r;++i){
        int z, g;
        cin >> z >> g;
        long long diff = g - f[z];
        f[z] = g;
        update_dp(n, z, diff, dp);
        cout << evaluate(n, dp) << "\n";
    }
}

