    for (int i = 0; i < m; ++i) {
        weights[i] = i + 1;
    }

    int result = 0;
    do {
        result = (result + count_mst(0, weights)) % MOD;
    } while (next_permutation(weights.begin(), weights.end()));

    cout << result;
}

