using namespace std;

void solve(const vector<int>& a, vector<int>& depth) {
    int n = a.size();
    stack<int> s;
    for (int i = 0; i < n; ++i) {
        while (!s.empty() && a[s.top()] < a[i]) {
            s.pop();
        }
        if (!s.empty()) {
            depth[a[i] - 1] = depth[a[s.top()] - 1] + 1;
        }
        s.push(i);
    }
}

