bool isCool(long long x, long long y) {
    if (y == 1) return true;
    long long sum = y * (y - 1) / 2;
    if ((x - sum) % y == 0 && (x - sum) / y >= 0) return true;
    sum = y * (y + 1) / 2;
    if ((x - sum) % y == 0 && (x - sum) / y >= 0) return true;
    return false;
}

