    // dp[r][c][0]: max a's for path ending at (r,c)
    // dp[r][c][1]: max b's for path ending at (r,c)
    vector<vector<vector<int>>> dp(n+1, vector<vector<int>>(n+1, vector<int>(2, 0)));
