    for(long long i=0;i<=n-k;i++){
        bool all_fixed = true;
        long long current_sum = 0;
        for(long long j=0;j<k;j++){
            if(!fixed[i+j]){
                all_fixed = false;
            }
            current_sum += a[i+j];
        }
        if(all_fixed){
            sums[i] = current_sum;
        }
