typedef long long ll;

bool compare(const pair<int, int>& a, const pair<int, int>& b) {
    ll lhs = (ll)(a.first - a.second) * (ll)b.second;
    ll rhs = (ll)(b.first - b.second) * (ll)a.second;
    return lhs > rhs;
}

int main(){
