using namespace std;

const int MAXN = 100005;
int id[MAXN], sz[MAXN], x[MAXN];
bool vis[MAXN];

int find(int a) {
    if (id[a] == a) return a;
    return id[a] = find(id[a]);
}

void uni(int a, int b, int d) {
    a = find(a), b = find(b);
    if (a == b) return;
    if (sz[a] > sz[b]) swap(a, b);
    id[a] = b;
    sz[b] += sz[a];
    x[a] = x[b] - d;
}

bool check(int a, int b, int d) {
    a = find(a), b = find(b);
    if (a != b) return false;
    return x[a] - x[b] == d;
}

