int dp[MAXN][MAXS];
int f[MAXS];

int mod_pow(int x, int y) {
    int res = 1;
    for (; y; y /= 2) {
        if (y % 2) res = 1LL * res * x % MOD;
        x = 1LL * x * x % MOD;
    }
    return res;
}

int inv(int x) {
    return mod_pow(x, MOD - 2);
}

int main(){
