        for(int j=0; j<=s; j++){
            for(int k=0; k+j<=s; k++){
                dp[i+1][j+k] = (dp[i+1][j+k] + dp[i][j]) % MOD;
            }
        }
    }
    for(int i=r; i<=s; i++){
        f[i] = dp[p][i];
    }
    for(int i=s-1; i>=0; i--){
        f[i] = (f[i] + f[i+1]) % MOD;
    }
    int total_ways = dp[p][s];
    int win_ways = 0;
    for(int i=r; i<=s; i++){
