        }
    }
    vector<vector<bool>> dp(p, vector<bool>(p));
    vector<int> comp_id(p, -1);
    int comp_cnt = 0;
    for(int i = 0; i < p; ++i){
        if(comp_id[i] == -1){
            queue<int> q;
            q.push(i);
            comp_id[i] = comp_cnt;
            while(!q.empty()){
                int u = q.front();
                q.pop();
                for(int v = 0; v < p; ++v){
                    if(A[u][v] && comp_id[v] == -1){
                        comp_id[v] = comp_cnt;
                        q.push(v);
                    }
                }
            }
            comp_cnt++;
        }
    }
    vector<int> comp_size(comp_cnt, 0);
    for(char c : s){
        comp_size[comp_id[c-'a']]++;
    }
    vector<bool> exists(comp_cnt, false);
    for(int i = 0; i < comp_cnt; ++i){
        exists[i] = (comp_size[i] > 0);
    }
    vector<int> G[comp_cnt];
    for(int i = 0; i < comp_cnt; ++i){
        for(int j = 0; j < comp_cnt; ++j){
            if(i != j){
                bool edge = false;
                for(int x = 0; x < p; ++x){
                    for(int y = 0; y < p; ++y){
                        if(comp_id[x] == i && comp_id[y] == j && A[x][y]){
                            edge = true;
                            break;
                        }
                    }
                    if(edge) break;
                }
                if(edge) G[i].push_back(j);
            }
        }
    }
    int ans = 0;
    for(int i = 0; i < comp_cnt; ++i){
        if(exists[i]){
            vector<bool> visited(comp_cnt, false);
            queue<int> q;
            q.push(i);
            visited[i] = true;
            int sum = 0;
            while(!q.empty()){
