                sum += comp_size[u];
                for(int v : G[u]){
                    if(!visited[v]){
                        visited[v] = true;
                        q.push(v);
                    }
                }
            }
            ans += (sum > 0 ? 1 : 0);
        }
    }
    cout << max(0, ans-1) << "\n";
}

