#include <bits/stdc++.h>
using namespace std;

const int MAXN = 100005;
const int LOGN = 20;

vector<int> adj[MAXN];
int dep[MAXN], par[MAXN][LOGN + 1], sz[MAXN], tin[MAXN], tout[MAXN], timer = 0;

void dfs(int u, int p) {
    par[u][0] = p;
    dep[u] = dep[p] + 1;
    tin[u] = ++timer;
    sz[u] = 1;
    for (int v : adj[u]) {
        if (v != p) {
            dfs(v, u);
            sz[u] += sz[v];
        }
    }
    tout[u] = timer;
}

void buildLCA(int n) {
    for (int j = 1; j <= LOGN; j++) {
        for (int i = 1; i <= n; i++) {
            if (par[i][j - 1] != -1) {
                par[i][j] = par[par[i][j - 1]][j - 1];
            }
        }
    }
}

int lca(int u, int v) {
    if (dep[u] < dep[v]) swap(u, v);
    for (int j = LOGN; j >= 0; j--) {
        if (dep[u] - (1 << j) >= dep[v]) {
            u = par[u][j];
        }
    }
    if (u == v) return u;
    for (int j = LOGN; j >= 0; j--) {
        if (par[u][j] != -1 && par[u][j] != par[v][j]) {
            u = par[u][j];
            v = par[v][j];
        }
    }
    return par[u][0];
}

bool is_ancestor(int u, int v) {
    return tin[u] <= tin[v] && tout[u] >= tout[v];
}

int kth_ancestor(int u, int k) {
    for (int j = LOGN; j >= 0; j--) {
        if (k & (1 << j)) {
            u = par[u][j];
        }
    }
    return u;
}

