    for (int i = 0; i < m; i++) {
        int id;
        cin >> id;
        for (auto &e : adj[1]) {
            if (e.idx == id) {
                e.type = 1 - e.type;
                break;
            }
        }
        for (auto &e : adj[adj[1][0].to]) {
            if (e.idx == id) {
                e.type = 1 - e.type;
                break;
            }
        }
        reroot(1, -1);
        int ans = 0;
        for (int j = 1; j <= n; j++) {
            ans = max(ans, st[j]);
        }
        cout << ans / 2 << "\n";
    }
}

